"""Authored English editorial pages. Run from the repository root after editing this file."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'static' / 'en'
ROOT.mkdir(exist_ok=True)
(ROOT/'articles').mkdir(exist_ok=True)


def page(title, description, body, cls='about-page'):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Horary</title><meta name="description" content="{escape(description,quote=True)}"><link rel="icon" href="/static/icon.svg"><link rel="stylesheet" href="/static/style.css?v=9"></head><body><header><a href="/" class="brand" aria-label="Horary home"><span class="brand-icon">✳</span> horary<span class="beta">BETA</span></a><nav><a class="nav-link" href="/articles">Articles</a><a class="nav-link" href="/about">How it works</a><a class="nav-link" href="/">Ask a question ↗</a></nav></header><main class="{cls}">{body}</main><footer><a class="brand" href="/">✳ horary</a><a href="/articles">Articles</a><a href="/about">How it works</a><a href="/technical">For developers</a><a href="https://github.com/dowid/dowidai-horary" target="_blank" rel="noopener noreferrer">Source code ↗</a></footer></body></html>'''


about = '''<nav class="about-toc"><a href="/about" aria-current="page">For users</a><a href="/technical">For developers</a></nav><div class="about-intro"><span class="eyebrow">A PLAIN-LANGUAGE GUIDE</span><h1>From your question<br>to a reading.</h1><p class="lead">You ask a question. The app calculates a chart of the sky for that moment, and AI helps you explore its symbols as a starting point for reflection.</p></div><aside class="summary-card"><p>This is an experimental symbolic reading. It does not predict the future with demonstrated accuracy or establish how another person feels.</p></aside>
<section id="steps"><span class="eyebrow">01 · YOUR QUESTION</span><h2>Your situation, in your words.</h2><p>Choose your own work or a relationship with a particular partner. Ask one specific question and select the city where you are now. You do not need your birth date. Leave out names, contact information and sensitive details.</p><p>The service records the time when it processes your request. A new request, even with the same wording, can therefore produce a different chart and explanation.</p></section>
<section id="engine"><span class="eyebrow">02 · THE CALCULATION</span><h2>Software calculates the planetary positions.</h2><p>We use <a href="https://www.astro.com/swisseph/swephinfo_e.htm">Swiss Ephemeris, a calculation engine for celestial positions ↗</a>. Using your city and the time, the application determines planetary positions and draws a chart.</p><p>The AI receives an already calculated chart; it does not work out where the planets are. Accurate astronomy does not establish that an interpretation can reliably predict your future.</p></section>
<section id="model"><span class="eyebrow">03 · THE EXPLANATION</span><h2>AI helps explain the result.</h2><div class="model-card"><span>Readings currently use this OpenAI model</span><strong>GPT-4.1 mini</strong><a href="https://developers.openai.com/api/docs/models/gpt-4.1-mini">About the model ↗</a></div><p>The model receives your question, the calculated chart and a limited set of interpretation rules. It writes a short summary, up to three observations and a question for reflection in your selected language. It may ask you to clarify an unsuitable question.</p><p>We check that the answer refers to existing chart facts and permitted rules. This does not eliminate errors in the explanation. Compare the text with what you actually know about your situation.</p></section>
<section id="limits"><span class="eyebrow">04 · WHAT TO EXPECT</span><h2>A perspective, without a final verdict.</h2><p>This is an early version. Some traditional methods are not implemented and interpretations have not undergone expert review. See the <a href="/technical#limitations">technical limitations</a>.</p><p>Readings should not promise exact dates, probabilities or definitive yes/no answers. They do not replace a conversation, evidence or professional support. Health, investments, legal disputes and other people's secrets are outside the service's scope.</p><p>The beta allows up to 10 reading attempts per browser in a rolling 24-hour period, with a one-minute pause between requests. A shared monthly budget also applies.</p></section>
<section><span class="eyebrow">05 · YOUR ARCHIVE</span><h2>Return to a question when you need to.</h2><p><strong>My questions</strong> stores your readings in this browser's private archive. Clearing the site's cookie or switching devices loses access; recovery is not yet available. Use <strong>Download reading</strong> to keep important results and download the chart as PNG or SVG.</p><p><strong>Share</strong> creates a link to one reading, including the question and city. Anyone who has it can open it. <strong>Revoke link</strong> removes that access; <strong>Delete</strong> removes the record from the live database. Copies already downloaded by someone else cannot be recalled.</p><p>Your question and chart are sent to OpenAI to generate the explanation. We keep the question, city, time, chart and answer until you delete them or the service ends. Provider backups can remain longer. The owner sees aggregate statistics, not question text in the dashboard.</p></section>
<section><h2>You can say it aloud.</h2><p>Choose <strong>Ask by voice</strong>, consent to sending the recording to OpenAI and allow microphone access. The bars respond to your voice. Record up to 30 seconds, stop, then review and edit the transcript. Your question is only submitted when you press <strong>Get a reading</strong>. Horary does not store audio. Voice input has a separate allowance of 10 attempts per 24 hours and uses the same shared monthly budget.</p></section>
<section><h2>Two languages, one archive.</h2><p>Choose English or Русский from the language menu. New readings and voice transcription use that language. Saved answers retain their original language; switching the interface does not rewrite them.</p><a class="about-cta" href="/technical">Explore the technical details ↗</a></section>'''
(ROOT/'about.html').write_text(page('How it works','Your question, the chart engine, AI explanations and your private archive.',about),encoding='utf-8')

technical = '''<nav class="about-toc"><a href="/about">For users</a><a href="/technical" aria-current="page">For developers</a></nav><div class="about-intro"><span class="eyebrow">FOR DEVELOPERS · VERSION 0.2</span><h1>Inside Horary.</h1><p class="lead">Astronomical calculation, application rules and generated text are separate parts of the system.</p></div><aside class="summary-card"><p>Question + city + server time → Swiss Ephemeris → chart facts and application rules → GPT-4.1 mini → response validation → private archive.</p></aside>
<section id="engine"><h2>Swiss Ephemeris and the Python wrapper.</h2><p><a href="https://www.astro.com/swisseph/swephinfo_e.htm">Swiss Ephemeris by Astrodienst</a> calculates planetary positions and speeds, the ascendant and Regiomontanus house cusps. We call <code>swe.calc_ut</code> with <code>FLG_MOSEPH | FLG_SPEED</code> and <code>swe.houses(..., b'R')</code>. Planetary calculations use the built-in Moshier algorithm, without external ephemeris files.</p><p>The installed wrapper is <a href="https://pypi.org/project/pysweph/2.10.3.6/">pysweph 2.10.3.6</a>, imported as <code>swisseph</code>. It continues pyswisseph, but the packages are not completely interchangeable: the application handles pysweph's unused house-array element zero.</p><p>Our code calculates seven traditional planets, signs, houses, retrograde motion and the ruler of house one and the selected topic house: seven for relationships, ten for career, four for home, nine for study and long-distance travel, eleven for friendship. Major aspects use 0°, 60°, 90°, 120° and 180°, with a fixed 6° display orb. SVG charts use the same calculated data; PNG export runs in the browser.</p><h3>What about Kerykeion?</h3><p><a href="https://github.com/g-battaglia/kerykeion">Kerykeion</a> is a higher-level astrology and charting library. It is not installed here: our code performs this layer's work on top of Swiss Ephemeris. Adding a library alone would not provide complete horary interpretation.</p></section>
<section id="architecture"><h2>From the browser to the archive.</h2><ul><li><strong>Interface:</strong> server-localized HTML, CSS and JavaScript; city search, voice input, chart, readings and archive.</li><li><strong>Backend:</strong> Python FastAPI on Vercel, responsible for validation, calculations and the OpenAI request.</li><li><strong>Cities:</strong> geonamescache 2.0.0, using GeoNames data. Coordinates come from the selected city ID. Time comes from the server in UTC.</li><li><strong>Storage:</strong> Neon PostgreSQL through psycopg. Tables store reports, monthly reservations and request throttles.</li></ul><p>A random HttpOnly cookie identifies the browser owner; the database stores its SHA-256 hash. Production cookies use Secure and SameSite=Strict. Public sharing tokens are passed in the URL fragment and then sent to the API in a POST body. Private read, share and delete operations check ownership.</p></section>
<section id="model"><h2>Current model: GPT-4.1 mini.</h2><div class="model-card"><strong>GPT-4.1 mini</strong><code>gpt-4.1-mini-2025-04-14</code><a href="https://developers.openai.com/api/docs/models/gpt-4.1-mini">Model documentation ↗</a><a href="https://developers.openai.com/api/docs/models">OpenAI model catalog ↗</a></div><p>The Chat Completions request contains the question, topic, chart and limited rules. There is no web search or previous-reading context. Output is JSON, with a 1,400-token cap, temperature 0.3 and a 45-second timeout. One attempt first classifies the question (up to 300 output tokens). A clear, supported question then makes a reading request (up to 1,400 output tokens). Ambiguous questions receive a follow-up before any chart is built; unsupported questions receive an explanation. Neither call is automatically retried. One budget reservation covers both bounded calls. Clarifications release the daily reading slot and one-minute cooldown immediately. Actual AI budget reservations are retained. A separate ceiling of 40 requests per browser per 24 hours limits abuse. Saved reading usage includes both calls; standalone clarifications are not included in the saved-report cost estimate.</p><p>Validation checks completion, status, text fields, one to three factors, existing fact IDs and allowed rule IDs. This is structural validation, not proof that the interpretation logically follows. Stored answers include model, prompt version, language and token usage.</p><p>The owner selects the model using <code>HORARY_AI_MODEL</code> and redeploys. An unapproved value disables new readings. Historical answers are not regenerated when the model or interface language changes.</p></section>
<section><h2>Budget reservations.</h2><p>A PostgreSQL transaction with an advisory lock enforces 10 reading attempts per browser over 24 hours, one attempt per IP per minute, and 380 paid calls per UTC calendar month. Readings and transcription share that monthly limit. Each permitted call reserves $0.05, without refunds on provider errors. The $19 reservation ceiling leaves $1 of a $20 budget as a buffer.</p><p>Input byte caps are 30,000 for mini and 12,000 for GPT-4.1. Pricing and limits must be reviewed when adding models. The application reservation is not the OpenAI account balance or a billing control on that account.</p></section>
<section id="limitations"><h2>A calculated chart is not a complete horary judgement.</h2><p>Dignities, receptions, translation and collection of light, void-of-course Moon and full aspect perfection before a sign change or station are not assessed. An applying flag only means the deviation from exactitude decreases one hour later.</p><p>The fixed 6° orb is a simplification. Absolute latitudes of 66° or more are rejected. Warnings about early or late ascendants, Saturn in the seventh house or shared rulers do not produce automatic verdicts. Expert review and reference cases are still needed.</p></section>
<section><h2>Voice input.</h2><p>MediaRecorder captures up to 30 seconds. Web Audio displays microphone levels and converts audio to mono PCM WAV at 16 kHz. The server validates the format and actual duration before calling OpenAI GPT-4o mini Transcribe. The selected language is passed to transcription. Audio is not stored. Users review the draft before submitting.</p><p>Voice attempts have separate daily and minute limits but share the monthly reservation budget. Cancelling an already sent request does not refund its reservation.</p></section>
<section><h2>Past and future events.</h2><p>Swiss Ephemeris finds each planet's nearest sign ingress, nearest retrograde and direct station, and nearest major aspect for each pair in either direction. The Sun and Moon have no stations. Search extends 1,096 days each way, using geocentric tropical longitudes, Moshier, six-hour brackets and root refinement below one second. Numerical precision is not a claim of subsecond physical accuracy.</p><p>Times are UTC. Positions refer to the first planet in each row; ingress rows show the new sign. This selected list is not a complete calendar and may differ from Sotis. Events are computed for display, including old readings; they are not passed to the interpretation model.</p></section>
<section><h2>Languages and owner statistics.</h2><p>Locales are registered centrally in <code>i18n.py</code>. Interface catalogs, server labels and editorial content are separate from calculations. English and Russian routes use language-specific canonical and alternate links. Calculations remain identical across languages.</p><p>The owner dashboard at <code>/admin</code> uses a separate password, signed eight-hour HttpOnly sessions and persistent login throttling. It returns aggregates only: saved readings, browser archives, languages, topics, models, feedback, recorded tokens and monthly reservations. Deleted readings and failed attempts are absent from report counts. Reservation totals include all admitted paid calls and are not actual spend.</p></section>
<section id="sources"><h2>Inspect the implementation.</h2><p><a href="https://github.com/dowid/dowidai-horary">Source code · AGPL-3.0-or-later ↗</a></p><p><a href="https://www.astro.com/swisseph/swephprg.htm">Swiss Ephemeris programming documentation ↗</a></p><a href="/about" class="about-cta">Back to the plain-language guide ↗</a></section>'''
(ROOT/'technical.html').write_text(page('Technical architecture','Swiss Ephemeris, Python, AI, languages, storage and limitations.',technical),encoding='utf-8')

articles = [
('what-is-horary','The chart of one question','What horary astrology is and why it does not need your birth date.',[
('A specific question at the centre','Horary astrology is a tradition of interpreting a chart drawn for the moment a question is asked. It focuses on one situation, such as work or a relationship. Natal astrology starts with a birth; horary starts with a question. This describes the tradition, not evidence of predictive accuracy.'),
('Why the moment matters','Deborah Houlding describes the chart in relation to the moment a question becomes clear and is presented for judgement. The idea is that celestial and human events can have a meaningful correspondence. This is a philosophical premise, not an established physical law. <a href="https://www.skyscript.co.uk/horary_intro.html">Read Houlding’s introduction</a>.'),
('One question makes the context clearer','“I am worried about work” can become “How can I reflect on the prospects of my current job?” The second version identifies the situation. Combining several unrelated questions makes it harder to understand what a reading refers to. Clear questions are useful regardless of your views on astrology.'),
('How this app works','Horary uses your selected city and the time the server processes the question. No birth date is needed. Software calculates the chart; AI explains a limited set of symbolic factors. The result is a reflection prompt, not a way to establish future events or another person’s feelings. <a href="/about">How it works</a>.')]),
('history','Why horary endures','William Lilly, a book from 1647, and questions about everyday life.',[
('A tradition concerned with practical questions','Horary belongs to the wider history of astrological divination. Its distinctive focus is a question about a concrete situation rather than a general portrait of a person. Relationships, work and missing objects are familiar topics in the tradition.'),
('William Lilly and Christian Astrology','The English astrologer William Lilly published Christian Astrology in 1647. It became an influential English-language source on traditional astrology, including detailed horary examples. Its historical importance does not establish that its judgements are reliable predictions. <a href="https://www.skyscript.co.uk/lilly.html">William Lilly at Skyscript</a>.'),
('Why people still study it','A defined question, a visible chart and a structured interpretation make the method attractive to people interested in traditional astrology. Modern schools and authors continue to teach it. Different practitioners can disagree about rules and how much weight each factor deserves.'),
('What we take from this history','The app makes the calculation and its limited rules visible. It does not claim to reproduce a complete historical consultation. Expert evaluation and documented reference cases are necessary before making stronger claims about the implementation.')]),
('methods','How a chart is read','Houses, planets and aspects: a brief guide to the language of horary.',[
('Houses describe areas of the question','Traditional readers associate houses with subjects. In this app, the first house represents the person asking, the seventh a particular partner, and the tenth the person’s own career. These are interpretation conventions, not physical properties of the sky. <a href="https://www.skyscript.co.uk/relationships.html">Houlding on relationship questions</a>.'),
('Planets act as significators','A significator is a planet chosen to represent a participant or topic. Selection follows the sign on a relevant house cusp and its traditional ruler. The Moon is an additional factor. A planet’s position does not directly reveal another person’s thoughts or intentions.'),
('Aspects describe angular relationships','Conjunctions, sextiles, squares, trines and oppositions correspond to particular angles. Our display uses a simplified 6° allowance. Applying means the angle moves closer to exactitude over the next hour; it does not prove the aspect will perfect before a change of direction or sign.'),
('What a fuller analysis would need','Traditional judgements can also consider dignities, receptions, translation and collection of light, and the Moon’s course. These are not yet implemented here. The current answer deliberately covers a limited set of factors. <a href="/technical#limitations">Implementation limitations</a>.')]),
('evidence','What can be checked','Where astronomical calculations end and interpretations begin.',[
('Planetary positions are calculable','Coordinates, speeds and house boundaries can be reproduced using the same time, location and settings. Our engine is <a href="https://www.astro.com/swisseph/swephinfo_e.htm">Swiss Ephemeris</a>. Agreement on coordinates is evidence about the calculation, not about the meaning assigned to it.'),
('Interpretation is a different claim','An accurate position does not demonstrate that it predicts a relationship or job outcome. Those claims need independent tests with clear criteria, comparison groups and outcomes assessed without hindsight. Personal impressions and memorable examples alone cannot settle the question.'),
('Research needs careful boundaries','Shawn Carlson’s 1985 double-blind test in Nature examined claims about natal astrology and personality. It is relevant to discussions of astrological evidence, but it is not a direct test of every horary rule or this application. <a href="https://www.nature.com/articles/318419a0">Read the study</a>.'),
('How to use this product','Treat the reading as symbolic material for reflection. Compare it with facts and conversations. The chart, model name, rules and limitations are visible so you can inspect what the app actually did. A helpful-sounding answer is not proof of a prediction, and an AI explanation can be wrong.')])
]

cards=[]
for i,(slug,title,description,sections) in enumerate(articles):
    toc=''.join(f'<a href="#part-{n}">{escape(h)}</a>' for n,(h,p) in enumerate(sections))
    content=''.join(f'<section id="part-{n}"><h2>{escape(h)}</h2><p>{p}</p></section>' for n,(h,p) in enumerate(sections))
    body=f'<a class="reading-back" href="/articles">← All articles</a><div class="reading-header"><span class="eyebrow">HORARY LIBRARY</span><h1>{title}</h1><p class="lead">{description}</p></div><div class="reading-layout"><nav class="reading-toc" aria-label="In this article">{toc}</nav><article>{content}<a class="reading-next" href="/articles"><span>KEEP EXPLORING</span><strong>Back to the library ↗</strong></a></article></div>'
    (ROOT/'articles'/(slug+'.html')).write_text(page(title,description,body,'reading-page'),encoding='utf-8')
    cards.append(f'<a class="journal-card tone-{i}" href="/articles/{slug}"><div class="journal-art"><svg viewBox="0 0 220 220" aria-hidden="true"><g fill="none" stroke="currentColor"><circle cx="110" cy="110" r="86"/><circle cx="110" cy="110" r="66" stroke-dasharray="2 7"/><path d="M64 62L142 113L81 151Z"/></g></svg><span>0{i+1}</span></div><div class="journal-card-copy"><div class="journal-meta">HORARY LIBRARY</div><h3>{title}</h3><p>{description}</p><span class="journal-read">Read article ↗</span></div></a>')
body='<div class="journal-heading"><span class="eyebrow">EXPLORE THE TRADITION</span><h1>Before reading<br><em>the stars.</em></h1><p>Understand the question, the chart and the limits of interpretation.</p></div><div class="journal-grid">'+''.join(cards)+'</div><p class="journal-note">These articles explain a tradition and the application. They do not establish astrology as a reliable way to predict events.</p>'
(ROOT/'articles'/'index.html').write_text(page('Articles','An introduction to horary astrology, its history, methods and evidence.',body,'journal-page'),encoding='utf-8')
